function juniorLevelFor(index) {
  if (index < 370) return '中1';
  if (index < 740) return '中2';
  return '中3';
}

function juniorIndexFor(index) {
  if (index < 370) return index;
  if (index < 740) return index - 370;
  return index - 740;
}

function levelUnit(level, index) {
  if (level.startsWith('中')) return `${level} 常用漢字 ${Math.floor(index / 90) + 1}`;
  return `${level} 配当漢字`;
}

function levelPrompt(level, reading) {
  const label = level.startsWith('中') ? `${level}相当で扱う常用漢字` : `${level}で習う漢字`;
  return `読み「${reading}」に合う、${label}を一字で書く。`;
}

