// 例文テンプレート内の {} を、答えを伏せた記号／答えそのものに置き換える。
// テンプレートに {} が無い旧データは、答えの文字列をそのまま伏せ字にする。
function maskSentence(sentence, answer) {
  const text = String(sentence || '');
  if (!text) return '';
  if (text.includes('{}')) return text.replace('{}', '〇〇');
  return answer ? text.split(answer).join('〇〇') : text;
}

function fillSentence(sentence, answer) {
  const text = String(sentence || '');
  if (!text) return '';
  if (text.includes('{}')) return text.replace('{}', String(answer || ''));
  return text;
}

function buildQuestionBank() {
  const rich = (typeof window !== 'undefined' && window.KanjiRich) ? window.KanjiRich : {};
  const items = [];
  Object.entries(GRADE_KANJI).forEach(([level, chars]) => {
    chars.forEach((baseChar, index) => {
      const itemLevel = level === '中学' ? juniorLevelFor(index) : level;
      const itemIndex = level === '中学' ? juniorIndexFor(index) : index;
      const id = `bank_${itemLevel}_${String(itemIndex + 1).padStart(4, '0')}`;
      const unit = levelUnit(itemLevel, itemIndex);
      const info = rich[baseChar];

      if (info) {
        // [音読み, 訓読み, 出題単語, 単語の読み, 例文({}=答え), 参考単語]
        const [on, kun, word, wordReading, sentence, refWords] = info;
        items.push({
          id,
          level: itemLevel,
          unit,
          baseChar,
          reading: wordReading,
          answer: word,
          onReading: on || '',
          kunReading: kun || '',
          refWords: refWords || '',
          prompt: `「${wordReading}」を漢字で書く。${/[ぁ-ん]$/.test(word) ? '送り仮名も正しく書きましょう。' : ''}`.trim(),
          example: maskSentence(sentence, word),
          exampleAnswer: fillSentence(sentence, word),
          expectedStrokes: null,
          tags: ['標準漢字']
        });
        return;
      }

      // リッチデータ未整備の漢字は従来どおり（小1は単語、それ以外は一字）。
      const wordObj = GRADE1_WORDS[baseChar];
      const answer = wordObj ? wordObj.answer : baseChar;
      const reading = wordObj ? wordObj.reading : (READINGS[baseChar] || baseChar);
      items.push({
        id,
        level: itemLevel,
        unit,
        baseChar,
        reading,
        answer,
        prompt: levelPrompt(itemLevel, reading),
        example: '',
        exampleAnswer: '',
        expectedStrokes: null,
        tags: ['標準漢字']
      });
    });
  });
  return items;
}

window.KanjiBank = {
  BANK_VERSION,
  GRADE_KANJI,
  READINGS,
  LEVELS,
  KYU_BY_LEVEL,
  maskSentence,
  fillSentence,
  buildQuestionBank
};
